Algorithm Prices
  Define prices As Vector<Integer> <- vector();
  Define entered As Integer;
  For i <- 1 To 5 Do
    Read entered;
    prices.append(entered);
  EndFor
  Define changed As Vector<Integer> <- vector();
  For Each price In prices Do
    changed.append(price + 1);
  EndFor
  Write changed;
  changed <- vector();
  For Each price In prices Do
    changed.append(price * 2);
  EndFor
  Write changed;
  changed <- vector();
  For Each price In prices Do
    changed.append(price - 1);
  EndFor
  Write changed;
EndAlgorithm

