Function next <- PlusOne(x As Integer)
  Define next As Integer;
  next <- x + 1;
EndFunction

Function twice <- Double(x As Integer)
  Define twice As Integer;
  twice <- x * 2;
EndFunction

Function previous <- MinusOne(x As Integer)
  Define previous As Integer;
  previous <- x - 1;
EndFunction

Function mapped <- Map(v As Vector<Integer>, f As Function(Integer) As Integer)
  Define mapped As Vector<Integer> <- vector();
  For Each item In v Do
    mapped.append(f(item));
  EndFor
EndFunction

Algorithm Prices
